#!/bin/sh
# One-way sync: this repo is the source of truth, ../../cadam is the installed
# sandbox with node_modules where the dev server and checks run.
#
# A mirror, not a copy. `cp -r` leaves deleted and renamed files behind in the
# sandbox, and a stale route file is worse than useless -- the TanStack plugin
# regenerates the route tree from whatever is on disk, so a renamed route shows
# up twice and the build fails somewhere unrelated.
#
# One file flows the other way: src/routeTree.gen.ts is generated by that
# plugin, which only runs in the sandbox. The Docker build runs `tsc -b`
# against whatever is committed, so a stale tree fails on every new route.
set -e
DEV="$(cd "$(dirname "$0")/../../cadam" && pwd)"
HERE="$(cd "$(dirname "$0")" && pwd)"

for d in src shared scripts; do
  rm -rf "$DEV/$d"
  cp -r "$HERE/$d" "$DEV/$d"
done
cp "$HERE/package.json" "$HERE/vite.config.ts" "$DEV/"

if [ -f "$DEV/src/routeTree.gen.ts" ]; then
  sleep 3   # let the dev server regenerate after the copy above
  cp "$DEV/src/routeTree.gen.ts" "$HERE/src/routeTree.gen.ts"
fi
echo "synced -> $DEV"
